-- Tag 2 (Samstag):  z_nr=2, abgeschlossen
-- Tag 3 (Sonntag):  z_nr=3, offen (aktueller Tag)
-- =============================================================================


SELECT setval(pg_get_serial_sequence('kassensitzungen', 'z_nr'), (SELECT MAX(z_nr) FROM kassensitzungen));


